from __future__ import annotations
import math


def generate_decision_support(row):
    score = int(row["severity_score"])
    conf_cat = row["confidence_category"]
    dice = row.get("case_dice", float("nan"))
    burden = float(row["predicted_tumor_burden"])
    affected = float(row["affected_slice_ratio"])
    uncertainty = float(row["uncertainty_ratio"])

    disclaimer = (
        "This output is generated by a research prototype and is not a medical diagnosis. "
        "A qualified radiologist or clinical specialist should review the complete MRI study and clinical context."
    )

    if score == 0:
        summary = "The model did not identify a meaningful whole-tumor region in the analyzed MRI slices. If symptoms or prior imaging suggest concern, specialist review remains appropriate."
        next_step = "Consider routine radiology review and correlation with the full imaging study, especially if MRI quality is limited."
        urgency = "Routine review"
        questions = ["Is there any subtle abnormality not captured by the model?", "Are additional MRI sequences or clinical history needed?", "Is follow-up imaging required based on the patient's clinical presentation?"]
    elif score in (1, 2):
        summary = "The model identified a relatively small imaging-derived tumor burden. The finding should be confirmed by expert radiology review."
        next_step = "Recommend specialist review of the MRI, comparison with any prior scan, and confirmation of the predicted tumor boundary."
        urgency = "Non-urgent specialist review"
        questions = ["Does the predicted region correspond to a true tumor abnormality?", "Is the tumor boundary consistent across FLAIR, T1CE, and T2 sequences?", "Is interval follow-up imaging recommended?"]
    elif score == 3:
        summary = "The model identified a moderate imaging-derived tumor burden. Structured specialist review is important."
        next_step = "Recommend timely neuroradiology review, confirmation with the full radiology report, and correlation with symptoms and prior imaging."
        urgency = "Timely specialist review"
        questions = ["What is the radiologist-confirmed tumor extent?", "Is there mass effect, edema, or enhancement that should be described?", "Should the case be reviewed by a multidisciplinary neuro-oncology team?"]
    else:
        summary = "The model identified a high imaging-derived tumor burden or broad slice involvement. This does not define clinical grade, but it indicates that expert review should not be delayed."
        next_step = "Recommend prompt neuroradiology or neuro-oncology review, confirmation of tumor extent, and integration with clinical findings."
        urgency = "Prompt specialist review"
        questions = ["Is there substantial mass effect, edema, enhancement, or midline shift?", "Does the predicted tumor extent agree with the radiologist's interpretation?", "Is urgent multidisciplinary clinical review appropriate based on the full clinical picture?"]

    modifiers = []
    if conf_cat == "Low confidence":
        modifiers.append("Model confidence is low or uncertainty is elevated; treat the output as provisional.")
    if uncertainty >= 0.10:
        modifiers.append("The uncertainty band around the threshold is relatively large; manual boundary verification is recommended.")
    try:
        if math.isfinite(float(dice)) and float(dice) < 0.70:
            modifiers.append("The case-level segmentation agreement is limited; interpret severity cautiously.")
    except Exception:
        pass
    if burden > 0 and affected < 0.03:
        modifiers.append("The predicted abnormality appears in relatively few slices; verify that it is not artifact.")

    return {
        "structured_summary": summary,
        "recommended_next_step": next_step,
        "urgency_category": urgency,
        "confidence_comment": conf_cat,
        "safety_modifiers": " ".join(modifiers) if modifiers else "No additional safety modifier triggered.",
        "suggested_questions_for_clinician": " | ".join(questions),
        "disclaimer": disclaimer,
    }
